1	/**
2	 * Hooks de inteligência financeira — Slice 3 (R12-R16).
3	 *
4	 * useSpendLimit: CRUD do teto de gasto mensal da empresa + faturamento declarado.
5	 * useFinancialBI: todos os indicadores BI do período (BI-1 a BI-5) + avaliação de alerta on-demand.
6	 *
7	 * Padrões do projeto:
8	 *  - useState + useEffect + supabase.from direto (Art. 5 — sem React Query).
9	 *  - Tipos à mão em types/index.ts (Art. 2).
10	 *  - Imports relativos (sem alias @/).
11	 *  - logError (nunca console.log).
12	 */
13	
14	import { useState, useEffect, useCallback } from 'react';
15	import { useNavigate } from 'react-router-dom';
16	import { supabase } from '../lib/supabase';
17	import { SpendLimitService } from '../services/spendLimitService';
18	import { FinancialBIService, currentMonthPeriod, type BIPeriod } from '../services/financialBIService';
19	import { logError } from '../lib/logger';
20	import type {
21	  SpendLimit,
22	  MonthlyRevenue,
23	  FinancialBIData,
24	} from '../types';
25	
26	// ---------------------------------------------------------------------------
27	// useSpendLimit — CRUD do teto + faturamento
28	// ---------------------------------------------------------------------------
29	
30	export interface UseSpendLimitResult {
31	  /** Teto configurado (null = não configurado). */
32	  spendLimit: SpendLimit | null;
33	  /** Faturamento declarado do mês de referência (null = não informado). */
34	  monthlyRevenue: MonthlyRevenue | null;
35	  loading: boolean;
36	  error: string | null;
37	  /**
38	   * Cria ou atualiza o teto de gasto mensal.
39	   * @returns true em caso de sucesso.
40	   */
41	  upsertSpendLimit: (params: {
42	    amount: number;
43	    alertThresholds?: number[];
44	    financialContactEmail?: string | null;
45	    financialContactPhone?: string | null;
46	  }) => Promise<boolean>;
47	  /**
48	   * Cria ou atualiza o faturamento declarado do mês.
49	   * @returns true em caso de sucesso.
50	   */
51	  upsertMonthlyRevenue: (amount: number, yearMonth?: Date | string) => Promise<boolean>;
52	  /** Recarregar dados. */
53	  refresh: () => void;
54	}
55	
56	/**
57	 * Hook para EMPRESA — gerenciar teto de gasto e faturamento declarado.
58	 *
59	 * @param yearMonth Mês de referência para o faturamento (default: mês corrente).
60	 */
61	export function useSpendLimit(yearMonth?: Date | string): UseSpendLimitResult {
62	  const [spendLimit, setSpendLimit] = useState<SpendLimit | null>(null);
63	  const [monthlyRevenue, setMonthlyRevenue] = useState<MonthlyRevenue | null>(null);
64	  const [loading, setLoading] = useState(true);
65	  const [error, setError] = useState<string | null>(null);
66	  const [companyId, setCompanyId] = useState<string | null>(null);
67	  const navigate = useNavigate();
68	
69	  // Mês de referência estável
70	  const refMonth: Date | string = yearMonth ?? new Date();
71	
72	  const load = useCallback(
73	    async (cid?: string) => {
74	      try {
75	        const {
76	          data: { user },
77	        } = await supabase.auth.getUser();
78	        if (!user) {
79	          navigate('/login');
80	          return;
81	        }
82	
83	        setLoading(true);
84	        setError(null);
85	
86	        let resolvedCompanyId = cid ?? companyId;
87	        if (!resolvedCompanyId) {
88	          const { data: company, error: cErr } = await supabase
89	            .from('companies')
90	            .select('id')
91	            .eq('owner_id', user.id)
92	            .maybeSingle();
93	          if (cErr) {
94	            logError('useSpendLimit.load.company', cErr);
95	            setError('Erro ao carregar dados da empresa.');
96	            setLoading(false);
97	            return;
98	          }
99	          if (!company) {
100	            setLoading(false);
101	            return;
102	          }
103	          resolvedCompanyId = company.id as string;
104	          setCompanyId(resolvedCompanyId);
105	        }
106	
107	        const [limit, revenue] = await Promise.all([
108	          SpendLimitService.getSpendLimit(resolvedCompanyId, null),
109	          SpendLimitService.getMonthlyRevenue(resolvedCompanyId, refMonth),
110	        ]);
111	
112	        setSpendLimit(limit);
113	        setMonthlyRevenue(revenue);
114	      } catch (err) {
115	        logError('useSpendLimit.load', err);
116	        setError('Erro ao carregar dados financeiros.');
117	      } finally {
118	        setLoading(false);
119	      }
120	    },
121	    // eslint-disable-next-line react-hooks/exhaustive-deps
122	    [navigate, companyId],
123	  );
124	
125	  useEffect(() => {
126	    let active = true;
127	    void (async () => {
128	      const {
129	        data: { user },
130	      } = await supabase.auth.getUser();
131	      if (!user) {
132	        navigate('/login');
133	        return;
134	      }
135	
136	      setLoading(true);
137	      setError(null);
138	
139	      const { data: company, error: cErr } = await supabase
140	        .from('companies')
141	        .select('id')
142	        .eq('owner_id', user.id)
143	        .maybeSingle();
144	
145	      if (cErr || !company) {
146	        if (active) {
147	          setLoading(false);
148	          if (cErr) setError('Erro ao carregar dados da empresa.');
149	        }
150	        return;
151	      }
152	
153	      const cid = company.id as string;
154	      if (active) setCompanyId(cid);
155	
156	      const [limit, revenue] = await Promise.all([
157	        SpendLimitService.getSpendLimit(cid, null),
158	        SpendLimitService.getMonthlyRevenue(cid, refMonth),
159	      ]);
160	
161	      if (!active) return;
162	      setSpendLimit(limit);
163	      setMonthlyRevenue(revenue);
164	      setLoading(false);
165	    })();
166	    return () => {
167	      active = false;
168	    };
169	    // eslint-disable-next-line react-hooks/exhaustive-deps
170	  }, [navigate]);
171	
172	  const upsertSpendLimit = useCallback(
173	    async (params: {
174	      amount: number;
175	      alertThresholds?: number[];
176	      financialContactEmail?: string | null;
177	      financialContactPhone?: string | null;
178	    }): Promise<boolean> => {
179	      if (!companyId) return false;
180	      const result = await SpendLimitService.upsertSpendLimit(companyId, params);
181	      if (!result) return false;
182	      setSpendLimit(result);
183	      return true;
184	    },
185	    [companyId],
186	  );
187	
188	  const upsertMonthlyRevenue = useCallback(
189	    async (amount: number, ym?: Date | string): Promise<boolean> => {
190	      if (!companyId) return false;
191	      const result = await SpendLimitService.upsertMonthlyRevenue(
192	        companyId,
193	        ym ?? refMonth,
194	        amount,
195	      );
196	      if (!result) return false;
197	      setMonthlyRevenue(result);
198	      return true;
199	    },
200	    // eslint-disable-next-line react-hooks/exhaustive-deps
201	    [companyId],
202	  );
203	
204	  return {
205	    spendLimit,
206	    monthlyRevenue,
207	    loading,
208	    error,
209	    upsertSpendLimit,
210	    upsertMonthlyRevenue,
211	    refresh: () => void load(),
212	  };
213	}
