215	// ---------------------------------------------------------------------------
216	// useFinancialBI — todos os indicadores do período
217	// ---------------------------------------------------------------------------
218	
219	export interface UseFinancialBIResult {
220	  data: FinancialBIData | null;
221	  loading: boolean;
222	  error: string | null;
223	  /** company_id resolvido (necessário para ações da UI). */
224	  companyId: string;
225	  /** Recarregar dados + disparar avaliação de alerta on-demand. */
226	  refresh: () => void;
227	}
228	
229	/**
230	 * Hook para EMPRESA — carregar todos os indicadores BI do período.
231	 * Avalia o alerta de teto on-demand ao carregar (best-effort, não bloqueia).
232	 *
233	 * @param period Período de análise. Default: mês corrente.
234	 */
235	export function useFinancialBI(period?: BIPeriod): UseFinancialBIResult {
236	  const [data, setData] = useState<FinancialBIData | null>(null);
237	  const [loading, setLoading] = useState(true);
238	  const [error, setError] = useState<string | null>(null);
239	  const [companyId, setCompanyId] = useState<string>('');
240	  const navigate = useNavigate();
241	
242	  const resolvedPeriod: BIPeriod = period ?? currentMonthPeriod();
243	
244	  const load = useCallback(
245	    async (cid?: string) => {
246	      try {
247	        const {
248	          data: { user },
249	        } = await supabase.auth.getUser();
250	        if (!user) {
251	          navigate('/login');
252	          return;
253	        }
254	
255	        setLoading(true);
256	        setError(null);
257	
258	        let resolvedCompanyId = cid ?? companyId;
259	        if (!resolvedCompanyId) {
260	          const { data: company, error: cErr } = await supabase
261	            .from('companies')
262	            .select('id')
263	            .eq('owner_id', user.id)
264	            .maybeSingle();
265	          if (cErr || !company) {
266	            setError('Empresa não encontrada.');
267	            setLoading(false);
268	            return;
269	          }
270	          resolvedCompanyId = company.id as string;
271	          setCompanyId(resolvedCompanyId);
272	        }
273	
274	        const biData = await FinancialBIService.getAllBI(resolvedCompanyId, resolvedPeriod);
275	        setData(biData);
276	
277	        // Avaliar alerta de teto on-demand (best-effort — não bloqueia UI)
278	        void SpendLimitService.evaluateSpendAlert(resolvedCompanyId).catch((alertErr) => {
279	          logError('useFinancialBI.evaluateSpendAlert', alertErr);
280	        });
281	      } catch (err) {
282	        logError('useFinancialBI.load', err);
283	        setError('Erro ao carregar indicadores financeiros.');
284	      } finally {
285	        setLoading(false);
286	      }
287	    },
288	    // eslint-disable-next-line react-hooks/exhaustive-deps
289	    [navigate, companyId, resolvedPeriod.start, resolvedPeriod.end],
290	  );
291	
292	  useEffect(() => {
293	    let active = true;
294	    void (async () => {
295	      const {
296	        data: { user },
297	      } = await supabase.auth.getUser();
298	      if (!user) {
299	        navigate('/login');
300	        return;
301	      }
302	
303	      setLoading(true);
304	      setError(null);
305	
306	      const { data: company, error: cErr } = await supabase
307	        .from('companies')
308	        .select('id')
309	        .eq('owner_id', user.id)
310	        .maybeSingle();
311	
312	      if (cErr || !company) {
313	        if (active) {
314	          setError('Empresa não encontrada.');
315	          setLoading(false);
316	        }
317	        return;
318	      }
319	
320	      const cid = company.id as string;
321	      if (active) setCompanyId(cid);
322	
323	      const biData = await FinancialBIService.getAllBI(cid, resolvedPeriod);
324	      if (!active) return;
325	
326	      setData(biData);
327	      setLoading(false);
328	
329	      // Avaliar alerta de teto on-demand (best-effort)
330	      void SpendLimitService.evaluateSpendAlert(cid).catch((alertErr) => {
331	        logError('useFinancialBI.evaluateSpendAlert', alertErr);
332	      });
333	    })();
334	    return () => {
335	      active = false;
336	    };
337	    // eslint-disable-next-line react-hooks/exhaustive-deps
338	  }, [navigate, resolvedPeriod.start, resolvedPeriod.end]);
339	
340	  return {
341	    data,
342	    loading,
343	    error,
344	    companyId,
345	    refresh: () => void load(),
346	  };
347	}
